  function filterProducts(items,filters={}){const terms=fold(filters.query).split(/\s+/).filter(Boolean);let out=items.filter(p=>terms.every(t=>fold([p.name,p.brand,p.ingredient,p.category,p.presentation].join(' ')).includes(t))&&(!filters.category||p.category===filters.category)&&(!filters.brand||p.brand===filters.brand)&&(!filters.ingredient||p.ingredient===filters.ingredient)&&(!filters.available||p.available)&&(!filters.sale||p.oldPrice)&&(!(filters.maxPrice>0)||p.price<=Number(filters.maxPrice)));if(filters.sort==='asc')out.sort((a,b)=>a.price-b.price);if(filters.sort==='desc')out.sort((a,b)=>b.price-a.price);if(filters.sort==='name')out.sort((a,b)=>a.name.localeCompare(b.name,'es'));return out;}
